CREATE OR REPLACE VIEW public.merchant_active_services_public AS SELECT msp.merchant_id,msp.service_id,mms.name AS service_name,msp.status,msp.expires_at FROM public.merchant_service_purchases msp JOIN public.merchant_market_services mms ON mms.id=msp.service_id JOIN public.merchants_public m ON m.id=msp.merchant_id WHERE msp.status='active' AND (msp.expires_at IS NULL OR msp.expires_at>now());
ALTER POLICY "Anyone can view active services" ON public.merchant_services USING (is_active=true AND EXISTS (SELECT 1 FROM public.merchants_public m WHERE m.id=merchant_services.merchant_id));
ALTER POLICY "Everyone can view active offers" ON public.partner_offers USING (is_active=true AND (partner_id IS NULL OR EXISTS (SELECT 1 FROM public.merchants_public m WHERE m.id=partner_offers.partner_id) OR EXISTS (SELECT 1 FROM public.partner_vets_public v WHERE v.id=partner_offers.partner_id)));